<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('campaigns.audit');$stats=db()->query("SELECT (SELECT COUNT(*) FROM spot_campaigns) spots,(SELECT COUNT(*) FROM video_categories) categories,(SELECT COUNT(*) FROM scan_audit_ledger WHERE status IN ('PASS','SETTLED')) successful,(SELECT COUNT(*) FROM scan_audit_ledger WHERE status IN ('WRONG_ATTEMPT','BLOCKED_DEVICE','EXHAUSTED')) failed,(SELECT COUNT(*) FROM qr_promo_grants WHERE status='ACTIVE') pending_ttl,(SELECT COALESCE(SUM(amount),0) FROM qr_promo_grants WHERE status IN ('EXPIRED','REVERSED')) reversed")->fetch();$rows=db()->query('SELECT a.*,s.spot_name,c.name category,u.name user_name FROM scan_audit_ledger a JOIN spot_campaigns s ON s.spot_id=a.spot_id LEFT JOIN video_categories c ON c.id=s.category_id JOIN users u ON u.id=a.user_id ORDER BY a.audit_id DESC LIMIT 500')->fetchAll();$pageTitle='Campaign history & audit';$pageSubtitle='Category-wise verification ledger, answers, devices and reward states';require APP_ROOT.'/includes/header.php';?><div class="grid stats"><div class="card"><span class="label">Total spots</span><span class="value"><?=e($stats['spots'])?></span></div><div class="card"><span class="label">Categories</span><span class="value"><?=e($stats['categories'])?></span></div><div class="card"><span class="label">Successful rewards</span><span class="value"><?=e($stats['successful'])?></span></div><div class="card"><span class="label">Failed / blocked</span><span class="value"><?=e($stats['failed'])?></span></div><div class="card"><span class="label">Pending TTL grants</span><span class="value"><?=e($stats['pending_ttl'])?></span></div><div class="card"><span class="label">Expired / reversed</span><span class="value"><?=money($stats['reversed'])?></span></div></div><section class="panel"><h2>Live scan audit ledger</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Spot / category</th><th>User</th><th>Device</th><th>Question answer</th><th>Distance</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['spot_id'])?><br><small><?=e($r['category']??'—')?></small></td><td><?=e($r['user_name'])?></td><td><?=e($r['device_hash'])?></td><td><?=e($r['user_input_answer']??'—')?></td><td><?=e($r['distance_calculated_m']??'—')?> m</td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No campaign scan records yet.</div><?php endif?></div></section><?php require APP_ROOT.'/includes/footer.php';
